#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, sz;

    DSU(int n) : p(n), sz(n, 1) {
        iota(p.begin(), p.end(), 0);
    }

    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }

    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<pair<int, int>> heights(N);

    for (int i = 0; i < N; i++) {
        int a;
        cin >> a;
        heights[i] = {a, i};
    }

    sort(heights.begin(), heights.end(), [](const auto &a, const auto &b) {
        return a.first > b.first;
    });

    DSU dsu(N);
    vector<char> active(N, false);

    int components = 0;
    int best = 0;

    for (int l = 0; l < N; ) {
        int r = l;
        while (r < N && heights[r].first == heights[l].first) {
            r++;
        }

        for (int k = l; k < r; k++) {
            int idx = heights[k].second;
            active[idx] = true;
            components++;
        }

        for (int k = l; k < r; k++) {
            int idx = heights[k].second;

            if (idx > 0 && active[idx - 1]) {
                if (dsu.unite(idx, idx - 1)) components--;
            }

            if (idx + 1 < N && active[idx + 1]) {
                if (dsu.unite(idx, idx + 1)) components--;
            }
        }

        best = max(best, components);
        l = r;
    }

    cout << best + 1 << '\n';

    return 0;
}
